// Terminal shell execution — SSE streaming, sandboxed to project root
router.post('/terminal/run', authMiddleware, (req, res) => {
    const { command } = req.body;
    if (typeof command !== 'string' || !command.trim()) {
        return res.status(400).json({ error: 'command required' });
    }
    let child: ReturnType<typeof spawn>;
    try {
        child = spawn('/bin/sh', ['-c', command], {
            cwd: SystemConfig.ROOT,
            env: process.env,
            stdio: ['pipe', 'pipe', 'pipe'],
            detached: false,
        });
        child.stdin?.end();
    } catch (err: any) {
        return res.status(500).json({ error: err.message });
    }
    res.writeHead(200, {
        'Content-Type': 'text/event-stream',
        'Cache-Control': 'no-cache',
        'Connection': 'keep-alive',
    });
    const send = (obj: object) => { try { res.write(`data: ${JSON.stringify(obj)}\n\n`); } catch {} };
    const cleanup = () => {
        try { child!.stdout?.destroy(); } catch {}
        try { child!.stderr?.destroy(); } catch {}
    };
    child.stdout!.on('error', () => {});
    child.stderr!.on('error', () => {});

