// Terminal shell execution — SSE + spawnSync fallback (async spawn EBADF under pm2/ts-node)
router.post('/terminal/run', authMiddleware, (req, res) => {
    const { command } = req.body;
    if (typeof command !== 'string' || !command.trim()) {
        return res.status(400).json({ error: 'command required' });
    }

    // Try async spawn first; fall back to spawnSync (blocks event loop briefly but works under pm2+ts-node EBADF)
    let child: ReturnType<typeof spawn> | null = null;
    let syncFallback = false;
    try {
        child = spawn('/bin/sh', ['-c', command], {
            cwd: SystemConfig.ROOT,
            env: process.env,
            stdio: ['pipe', 'pipe', 'pipe'],
        });
        child.stdin?.end();
    } catch {
        syncFallback = true;
    }

    if (syncFallback) {
        const result = spawnSync('/bin/sh', ['-c', command], {
            cwd: SystemConfig.ROOT,
            env: process.env,
            encoding: 'buffer',
            timeout: 30000,
            maxBuffer: 10 * 1024 * 1024,
        });
        res.writeHead(200, { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache', 'Connection': 'keep-alive' });
        if (result.error) { res.write(`data: ${JSON.stringify({ type: 'stderr', data: result.error.message })}\n\n`); }
        if (result.stdout?.length) { res.write(`data: ${JSON.stringify({ type: 'stdout', data: result.stdout.toString() })}\n\n`); }
        if (result.stderr?.length) { res.write(`data: ${JSON.stringify({ type: 'stderr', data: result.stderr.toString() })}\n\n`); }
        res.write(`data: ${JSON.stringify({ type: 'exit', code: result.status ?? 0 })}\n\n`);
        res.end();
        return;
    }

    res.writeHead(200, {
        'Content-Type': 'text/event-stream',
        'Cache-Control': 'no-cache',
        'Connection': 'keep-alive',
    });
    const send = (obj: object) => { try { res.write(`data: ${JSON.stringify(obj)}\n\n`); } catch {} };
    const cleanup = () => {
        try { child!.stdout?.destroy(); } catch {}
        try { child!.stderr?.destroy(); } catch {}
    };
    child!.stdout!.on('error', () => {});
    child!.stderr!.on('error', () => {});
    child!.stdout!.on('data', (d: Buffer) => send({ type: 'stdout', data: d.toString() }));
    child!.stderr!.on('data', (d: Buffer) => send({ type: 'stderr', data: d.toString() }));
    let done = false;
    child!.on('error', (err: Error) => { done = true; send({ type: 'stderr', data: err.message }); cleanup(); res.end(); });
    child!.on('close', (code: number | null) => { done = true; cleanup(); send({ type: 'exit', code }); res.end(); });
    res.on('close', () => { if (!done) { try { child!.kill(); } catch {} } });
});

