1	import fs from 'fs';
2	import path from 'path';
3	import { JSDOM } from 'jsdom';
4	import { Readability } from '@mozilla/readability';
5	import { neuralForge } from './neuralForgeService';
6	import { notebookTranscribe } from './notebookTranscribeService';
7	import { NotebookService } from './notebookService';
8	import { SystemConfig } from '../config/SystemConfig';
9	
10	const AUDIO_EXTS = new Set(['.mp3', '.mp4', '.m4a', '.wav', '.ogg', '.flac', '.webm']);
11	
12	export interface IngestResult {
13	    sourceId: number;
14	    chunkCount: number;
15	    wordCount: number;
16	}
17	
18	export class NotebookIngestService {
19	    private notebookService: NotebookService;
20	
21	    constructor(notebookService: NotebookService) {
22	        this.notebookService = notebookService;
23	    }
24	
25	    async ingestFile(notebookId: number, filePath: string, mimeType: string, originalName: string): Promise<IngestResult> {
26	        const ext = path.extname(originalName).toLowerCase();
27	        const stats = fs.statSync(filePath);
28	
29	        let text = '';
30	        let sourceType: 'pdf' | 'docx' | 'audio' | 'video' | 'url' | 'obsidian' = 'pdf';
31	        let metadata: Record<string, unknown> = {};
32	
33	        if (ext === '.pdf' || mimeType === 'application/pdf') {
34	            sourceType = 'pdf';
35	            text = await this.extractPdf(filePath);
36	        } else if (ext === '.docx' || mimeType.includes('wordprocessingml')) {
37	            sourceType = 'docx';
38	            text = await this.extractDocx(filePath);
39	        } else if (AUDIO_EXTS.has(ext) || mimeType.startsWith('audio/') || mimeType.startsWith('video/')) {
40	            sourceType = ext === '.mp4' || mimeType.startsWith('video/') ? 'video' : 'audio';
41	            const transcript = await notebookTranscribe.transcribe(filePath);
42	            text = transcript.text;
43	            metadata = { provider: transcript.provider, durationSeconds: transcript.durationSeconds };
44	        } else {
45	            throw new Error(`Unsupported file type: ${ext}`);
46	        }
47	
48	        const source = this.notebookService.createSource(notebookId, sourceType, originalName, {
49	            originPath: filePath,
50	            fileSizeBytes: stats.size,
51	            mimeType,
52	            metadata
53	        });
54	
55	        return this.processTextIntoChunks(source.id, text);
56	    }
57	
58	    async ingestUrl(notebookId: number, url: string): Promise<IngestResult> {
59	        const source = this.notebookService.createSource(notebookId, 'url', url, {
60	            originPath: url
61	        });
62	
63	        try {
64	            this.notebookService.updateSourceStatus(source.id, 'processing');
65	            const text = await this.fetchAndExtractUrl(url);
66	            return await this.processTextIntoChunks(source.id, text);
67	        } catch (e: any) {
68	            this.notebookService.updateSourceStatus(source.id, 'error', e.message);
69	            throw e;
70	        }
71	    }
72	
73	    async ingestObsidianNote(notebookId: number, vaultRelativePath: string): Promise<IngestResult> {
74	        const fullPath = SystemConfig.resolve(vaultRelativePath);
75	        if (!fs.existsSync(fullPath)) throw new Error(`Vault note not found: ${vaultRelativePath}`);
76	
77	        const raw = fs.readFileSync(fullPath, 'utf-8');
78	        // Strip YAML frontmatter
79	        const text = raw.replace(/^---[\s\S]*?---\n?/, '').trim();
80	        const title = path.basename(vaultRelativePath, '.md');
81	
82	        const source = this.notebookService.createSource(notebookId, 'obsidian', title, {
83	            obsidianPath: vaultRelativePath,
84	            fileSizeBytes: Buffer.byteLength(raw, 'utf-8')
85	        });
86	
87	        return this.processTextIntoChunks(source.id, text);
88	    }
89	
90	    private async extractPdf(filePath: string): Promise<string> {
91	        const mod = await import('pdf-parse');
92	        const pdfParse = typeof mod.default === 'function' ? mod.default : (mod as any);
93	        const buffer = fs.readFileSync(filePath);
94	        const result = await pdfParse(buffer);
95	        return result.text;
96	    }
97	
98	    private async extractDocx(filePath: string): Promise<string> {
99	        const mammoth = await import('mammoth');
100	        const result = await mammoth.extractRawText({ path: filePath });
101	        return result.value;
102	    }
103	
104	    private async fetchAndExtractUrl(url: string): Promise<string> {
105	        const resp = await fetch(url, {
106	            headers: { 'User-Agent': 'Mozilla/5.0 (compatible; NUDIMMUD/1.0)' },
107	            signal: AbortSignal.timeout(15000)
108	        });
109	        if (!resp.ok) throw new Error(`HTTP ${resp.status} fetching ${url}`);
110	        const html = await resp.text();
111	
112	        const dom = new JSDOM(html, { url });
113	        const reader = new Readability(dom.window.document);
114	        const article = reader.parse();
115	        return article?.textContent?.trim() || dom.window.document.body?.textContent?.trim() || '';
116	    }
117	
118	    private async processTextIntoChunks(sourceId: number, text: string): Promise<IngestResult> {
119	        try {
120	            this.notebookService.updateSourceStatus(sourceId, 'processing');
121	
122	            const words = text.split(/\s+/).filter(Boolean);
123	            const wordCount = words.length;
124	            const rawChunks = this.chunkText(words);
125	
126	            this.notebookService.saveChunks(sourceId, rawChunks);
127	            this.notebookService.updateSourceStatus(sourceId, 'processing', undefined, wordCount);
128	
129	            // Embed asynchronously (don't block the response)
130	            this.embedAllChunks(sourceId, rawChunks.length).catch(e =>
131	                console.error(`⬡ NOTEBOOK_EMBED_ERROR :: source=${sourceId} :: ${e.message}`)
132	            );
133	
134	            // Set status to ready immediately — embeddings fill in async
135	            this.notebookService.updateSourceStatus(sourceId, 'ready', undefined, wordCount);
136	
137	            return { sourceId, chunkCount: rawChunks.length, wordCount };
138	        } catch (e: any) {
139	            this.notebookService.updateSourceStatus(sourceId, 'error', e.message);
140	            throw e;
141	        }
142	    }
143	
144	    private chunkText(words: string[], windowTokens = 512, overlapTokens = 64): Array<{ content: string; tokenCount: number }> {
145	        const wordsPerWindow = Math.floor(windowTokens / 1.35);
146	        const wordsPerOverlap = Math.floor(overlapTokens / 1.35);
147	        const minWords = Math.floor(50 / 1.35);
148	        const chunks: Array<{ content: string; tokenCount: number }> = [];
149	
150	        let start = 0;
151	        while (start < words.length) {
152	            const end = Math.min(start + wordsPerWindow, words.length);
153	            const slice = words.slice(start, end);
154	            if (slice.length >= minWords) {
155	                const content = slice.join(' ');
156	                chunks.push({ content, tokenCount: Math.ceil(slice.length * 1.35) });
157	            }
158	            if (end >= words.length) break;
159	            start += (wordsPerWindow - wordsPerOverlap);
160	        }
161	        return chunks;
162	    }
163	
164	    private async embedAllChunks(sourceId: number, expectedCount: number): Promise<void> {
165	        const chunks = this.notebookService.getChunksForSource(sourceId);
166	        for (const chunk of chunks) {
167	            const embedding = await neuralForge.getEmbedding(chunk.content);
168	            if (embedding) {
169	                this.notebookService.updateChunkEmbedding(chunk.id, embedding);
170	            }
171	        }
172	        console.log(`⬡ NOTEBOOK_EMBED_DONE :: source=${sourceId} :: ${chunks.length}/${expectedCount} chunks embedded`);
173	    }
174	}

